INSERT INTO `ag_templates`(`id`,`author`,`author_name`,`name`,`description`,`instruction`,`trigger_json`,`copies`,`created_at`) VALUES('tpl-evening-sweep','aeka','Aeka','Evening overdue sweep','Every weekday at 6 pm: your overdue to-dos, Workflow tasks and missed reminders in one notification.','List my overdue to-dos, my overdue Workflow tasks and any reminders I missed today, using my_work. If there is anything, notify me with one short list, most overdue first, with the due date of each. If nothing is overdue, do not notify me. Keep notes of what you reported, and next time mention an item again only if it is still overdue, saying for how many days.','{"type":"schedule","repeat":"weekdays","at":1793017800000}',0,1793088000000);--> statement-breakpoint
INSERT INTO `ag_templates`(`id`,`author`,`author_name`,`name`,`description`,`instruction`,`trigger_json`,`copies`,`created_at`) VALUES('tpl-morning-deadlines','aeka','Aeka','Morning deadline check','Every weekday at 9 am: mandate deadlines in the next 7 days and tasks due this week; asks to create a preparation task where none exists.','Check mandate deadlines in the next 7 days and my Workflow tasks due this week, using my_work. Notify me with a short list by date. For any deadline within 2 days that has no open task on its mandate, ask me to approve a Workflow task to prepare for it (request_task), unassigned, due the day before the deadline.','{"type":"schedule","repeat":"weekdays","at":1792985400000}',0,1793088000001);--> statement-breakpoint
INSERT INTO `ag_templates`(`id`,`author`,`author_name`,`name`,`description`,`instruction`,`trigger_json`,`copies`,`created_at`) VALUES('tpl-urgent-email','aeka','Aeka','Urgent email handler','When an urgent email arrives: a high-priority to-do and a short holding reply ready in Mail > Drafts, never sent without you.','For each urgent email that started this run: find it with mail_queue (view needs_me), add a high-priority to-do to deal with it that names the sender and the subject, and prepare a short, courteous holding reply as an email draft (draft_email_reply) saying that I have seen it and will revert shortly. Notify me that the draft is ready in Mail > Drafts. Do not ask to send it.','{"type":"event","kinds":["mail.urgent"],"contains":""}',0,1793088000002);--> statement-breakpoint
INSERT INTO `ag_templates`(`id`,`author`,`author_name`,`name`,`description`,`instruction`,`trigger_json`,`copies`,`created_at`) VALUES('tpl-chats-digest','aeka','Aeka','Chats waiting digest','Every weekday at 1 pm: the chats from your phone that have waited longest for your reply.','List the chats from my phone waiting for my reply (phone_chats). If any have waited more than 3 hours, notify me with the five most pressing, each with the app, how long it has waited and what it is about. If none, do not notify me.','{"type":"schedule","repeat":"weekdays","at":1792999800000}',0,1793088000003);--> statement-breakpoint
INSERT INTO `ag_templates`(`id`,`author`,`author_name`,`name`,`description`,`instruction`,`trigger_json`,`copies`,`created_at`) VALUES('tpl-friday-followups','aeka','Aeka','Friday follow-up sweep','Every Friday at 4 pm: emails still unanswered after 5 days, with polite follow-up drafts for the three oldest.','List the email threads where I have been waiting for a reply (follow_ups, kind waiting). For the three that have waited longest, 5 days or more, prepare a polite follow-up draft to the last email of each (draft_email_reply). Notify me with the list and say the drafts are ready in Mail > Drafts. Do not ask to send them.','{"type":"schedule","repeat":"weekly","at":1793356200000}',0,1793088000004);
